const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const page = targets.find(t => t.type === 'page');
  if (!page) throw new Error('No Chromium page found');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0; const pending = new Map();
  ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  const send = (method, params = {}) => new Promise(resolve => { const n = ++id; pending.set(n, resolve); ws.send(JSON.stringify({id:n, method, params})); });
  const evaluate = async expression => (await send('Runtime.evaluate', {expression, returnByValue:true})).result.result.value;
  await send('Page.enable'); await send('Runtime.enable');
  await sleep(900);
  await evaluate("document.getElementById('startButton').click()");
  await sleep(1700);
  const start = await evaluate("({wave:document.getElementById('waveNumber').textContent, ammo:document.getElementById('ammoClip').textContent, health:document.getElementById('healthText').textContent, menuHidden:document.getElementById('startScreen').classList.contains('dismissed'), canvas:[document.getElementById('gameCanvas').width,document.getElementById('gameCanvas').height]})");
  await send('Page.captureScreenshot', {format:'jpeg', quality:74, captureBeyondViewport:false}).then(r => fs.writeFileSync('/tmp/opencode/deadsignal-gameplay.jpg', Buffer.from(r.result.data,'base64')));
  await send('Input.dispatchMouseEvent', {type:'mouseMoved', x:890, y:450});
  await send('Input.dispatchMouseEvent', {type:'mousePressed', x:890, y:450, button:'left', clickCount:1});
  await send('Input.dispatchMouseEvent', {type:'mouseReleased', x:890, y:450, button:'left', clickCount:1});
  await sleep(180);
  const afterShot = await evaluate("document.getElementById('ammoClip').textContent");
  await send('Input.dispatchKeyEvent', {type:'keyDown', key:'Escape', code:'Escape', windowsVirtualKeyCode:27});
  await send('Input.dispatchKeyEvent', {type:'keyUp', key:'Escape', code:'Escape', windowsVirtualKeyCode:27});
  const paused = await evaluate("!document.getElementById('pauseScreen').classList.contains('hidden')");
  console.log(JSON.stringify({start, ammoAfterShot:afterShot, pauseOverlayVisible:paused, screenshot:'/tmp/opencode/deadsignal-gameplay.jpg'}, null, 2));
  ws.close();
})().catch(e => { console.error(e); process.exit(1); });
